  for(const f of stage.fish){const [x,y]=f,xx=px(x),zz=pz(y);const group=new T.Group();group.position.set(xx,0,zz);this.room.add(group);box(group,white,0,.39,0,.82,.78,.82);box(group,trim,0,.81,0,.96,.12,.96);box(group,gold,0,.40,.421,.38,.12,.025);const trophy=new T.Group();group.add(trophy);const body=mesh(trophy,fishGeo,std(index===2?0xf0ca6b:0xe2c58c,{metalness:.65,roughness:.3}),0,1.20,-.08);ball(trophy,dark,.25,1.23,.09,.025,.025,.025);const halo=mesh(group,new T.TorusGeometry(.54,.012,6,48),new T.MeshBasicMaterial({color:0xf8dea0,transparent:true,opacity:.5}),0,.10,0);halo.rotation.x=Math.PI/2;this.exhibits.push({group,trophy,halo});}
