   this.yarn.visible=!!game.yarn;if(game.yarn){this.yarn.position.set(px(game.yarn.x),.17,pz(game.yarn.y));this.yarn.rotation.x=time*4;}
   this.camera.fov=43;this.camera.updateProjectionMatrix();let cx,cy,cz,tx,ty,tz;if(this.mode==='overview'){const elevation=Math.max(.55,Math.min(1.25,this.pitch+.08)),radius=25.5*this.zoom;cx=Math.sin(this.yaw)*Math.cos(elevation)*radius;cy=Math.sin(elevation)*radius;cz=Math.cos(this.yaw)*Math.cos(elevation)*radius;tx=0;ty=0;tz=.2;}else{tx=px(game.player.x);ty=.30;tz=pz(game.player.y);const radius=10*this.zoom,horizontal=Math.cos(this.pitch)*radius;cx=tx+Math.sin(this.yaw)*horizontal;cy=ty+Math.sin(this.pitch)*radius;cz=tz+Math.cos(this.yaw)*horizontal;}
