 rotate(dx,dy=0){if(this.inspect){this.inspectYaw+=dx;this.inspectPitch=Math.max(-.12,Math.min(.65,this.inspectPitch+dy));}else{this.yaw+=dx;this.pitch=Math.max(.36,Math.min(1.15,this.pitch+dy));}}
